package pl.zagranietyper.repository;import pl.zagranietyper.model.FootballCompetitionProgressionSnapshot;import java.sql.*;import java.time.Instant;import java.util.*;
public final class FootballCompetitionProgressionRepository {private final Database db;public FootballCompetitionProgressionRepository(Database d){db=d;}public void store(FootballCompetitionProgressionSnapshot s){try(Connection c=db.openConnection()){c.setAutoCommit(false);try{var old=status(c,s.leagueId(),s.season(),true);if(old==FootballCompetitionProgressionSnapshot.Status.COMPLETE&&s.status()!=FootballCompetitionProgressionSnapshot.Status.COMPLETE){c.rollback();return;}try(var p=c.prepareStatement("INSERT INTO api_football_competition_progression_fetches VALUES(?,?,?,?::jsonb,?,?) ON CONFLICT(league_id,season)DO UPDATE SET status=EXCLUDED.status,raw_json=EXCLUDED.raw_json,error_message=EXCLUDED.error_message,fetched_at=EXCLUDED.fetched_at")){p.setLong(1,s.leagueId());p.setInt(2,s.season());p.setString(3,s.status().name());p.setString(4,s.rawJson());p.setString(5,s.error());p.setTimestamp(6,Timestamp.from(s.fetchedAt()));p.executeUpdate();}if(s.status()==FootballCompetitionProgressionSnapshot.Status.COMPLETE){try(var p=c.prepareStatement("DELETE FROM api_football_competition_progression_fixtures WHERE league_id=? AND season=?")){p.setLong(1,s.leagueId());p.setInt(2,s.season());p.executeUpdate();}insert(c,s);}c.commit();}catch(Exception e){c.rollback();throw e;}}catch(Exception e){throw new IllegalStateException("progression store",e);}}public FootballCompetitionProgressionSnapshot.Status status(long l,int s){try(Connection c=db.openConnection()){return status(c,l,s,false);}catch(SQLException e){throw new IllegalStateException(e);}}private FootballCompetitionProgressionSnapshot.Status status(Connection c,long l,int s,boolean lock)throws SQLException{try(var p=c.prepareStatement("SELECT status FROM api_football_competition_progression_fetches WHERE league_id=? AND season=?"+(lock?" FOR UPDATE":""))){p.setLong(1,l);p.setInt(2,s);try(var r=p.executeQuery()){return r.next()?FootballCompetitionProgressionSnapshot.Status.valueOf(r.getString(1)):null;}}}public List<FootballCompetitionProgressionSnapshot.Fixture>load(long l,int s){String q="SELECT fixture_id,round,status_short,kickoff,home_team_id,home_team_name,home_winner,away_team_id,away_team_name,away_winner,goals_home,goals_away,ft_home,ft_away,et_home,et_away,pen_home,pen_away FROM api_football_competition_progression_fixtures WHERE league_id=? AND season=? ORDER BY kickoff,fixture_id";try(Connection c=db.openConnection();var p=c.prepareStatement(q)){p.setLong(1,l);p.setInt(2,s);try(var r=p.executeQuery()){List<FootballCompetitionProgressionSnapshot.Fixture>o=new ArrayList<>();while(r.next())o.add(new FootballCompetitionProgressionSnapshot.Fixture(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),nl(r,5),r.getString(6),nb(r,7),nl(r,8),r.getString(9),nb(r,10),ni(r,11),ni(r,12),ni(r,13),ni(r,14),ni(r,15),ni(r,16),ni(r,17),ni(r,18)));return o;}}catch(SQLException e){throw new IllegalStateException(e);}}private void insert(Connection c,FootballCompetitionProgressionSnapshot s)throws SQLException{String q="INSERT INTO api_football_competition_progression_fixtures VALUES("+String.join(",",Collections.nCopies(20,"?"))+")";try(var p=c.prepareStatement(q)){for(var f:s.fixtures()){int i=1;p.setLong(i++,s.leagueId());p.setInt(i++,s.season());p.setLong(i++,f.fixtureId());p.setString(i++,f.round());p.setString(i++,f.status());p.setString(i++,f.kickoff());sl(p,i++,f.homeId());p.setString(i++,f.homeName());sb(p,i++,f.homeWinner());sl(p,i++,f.awayId());p.setString(i++,f.awayName());sb(p,i++,f.awayWinner());si(p,i++,f.goalsHome());si(p,i++,f.goalsAway());si(p,i++,f.ftHome());si(p,i++,f.ftAway());si(p,i++,f.etHome());si(p,i++,f.etAway());si(p,i++,f.penHome());si(p,i,f.penAway());p.addBatch();}p.executeBatch();}}private static void sl(PreparedStatement p,int i,Long v)throws SQLException{if(v==null)p.setNull(i,Types.BIGINT);else p.setLong(i,v);}private static void si(PreparedStatement p,int i,Integer v)throws SQLException{if(v==null)p.setNull(i,Types.INTEGER);else p.setInt(i,v);}private static void sb(PreparedStatement p,int i,Boolean v)throws SQLException{if(v==null)p.setNull(i,Types.BOOLEAN);else p.setBoolean(i,v);}private static Long nl(ResultSet r,int i)throws SQLException{long v=r.getLong(i);return r.wasNull()?null:v;}private static Integer ni(ResultSet r,int i)throws SQLException{int v=r.getInt(i);return r.wasNull()?null:v;}private static Boolean nb(ResultSet r,int i)throws SQLException{boolean v=r.getBoolean(i);return r.wasNull()?null:v;}}
